smart.css:
.smc-root{font-family:var(--smc-font-body);color:var(--smc-text);line-height:1.72;background:var(--smc-bg);font-size:16px;overflow:hidden}
.smc-root *{box-sizing:border-box}
.smc-root h2,.smc-root h3{font-family:var(--smc-font-heading);color:var(--smc-primary);line-height:1.25}
.smc-root h2{font-size:clamp(24px,3.2vw,34px);font-weight:700;letter-spacing:-.02em;margin:8px 0 18px}
.smc-root h3{font-size:21px;font-weight:700;margin:8px 0 12px}
.smc-root p{margin:0 0 14px}
.smc-kicker{display:inline-block;color:var(--smc-accent);font-weight:700;font-size:13px;letter-spacing:.08em;text-transform:uppercase}
.smc-intro{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(280px,.92fr);gap:34px;align-items:center;padding:36px;background:linear-gradient(135deg,var(--smc-surface),color-mix(in srgb,var(--smc-primary) 7%,var(--smc-bg)));border:1px solid var(--smc-border);border-radius:calc(var(--smc-radius) * 1.8)}
.smc-intro-copy{min-width:0}
.smc-intro-media{margin:0;min-width:0}
.smc-intro-media img{display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:calc(var(--smc-radius) * 1.4);box-shadow:0 16px 38px color-mix(in srgb,var(--smc-text) 16%,transparent);cursor:zoom-in}
.smc-intro-media figcaption{margin:10px 4px 0;text-align:center;color:var(--smc-muted);font-size:13px;line-height:1.5}
.smc-quickfacts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:24px}
.smc-quickfacts div{padding:14px 12px;background:color-mix(in srgb,var(--smc-bg) 86%,transparent);border:1px solid var(--smc-border);border-radius:var(--smc-radius)}
.smc-quickfacts strong,.smc-quickfacts span{display:block}
.smc-quickfacts strong{font-family:var(--smc-font-heading);color:var(--smc-primary);font-size:18px}
.smc-quickfacts span{margin-top:3px;color:var(--smc-muted);font-size:12px;line-height:1.35}
.smc-feature-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:24px}
.smc-feature{position:relative;padding:30px;border:1px solid var(--smc-border);border-radius:calc(var(--smc-radius) * 1.5);background:var(--smc-surface)}
.smc-feature-accent{background:linear-gradient(145deg,color-mix(in srgb,var(--smc-accent) 8%,var(--smc-bg)),var(--smc-surface))}
.smc-feature h2,.smc-feature h3{font-size:22px;margin-right:38px}
.smc-number{position:absolute;right:22px;top:20px;color:color-mix(in srgb,var(--smc-accent) 28%,transparent);font-family:var(--smc-font-heading);font-size:30px;font-weight:800}
.smc-colors,.smc-care,.smc-specs,.smc-faq{margin-top:24px;padding:34px;border:1px solid var(--smc-border);border-radius:calc(var(--smc-radius) * 1.5);background:var(--smc-bg)}
.smc-section-head{max-width:720px;margin-bottom:22px}
.smc-color-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.smc-color-card{margin:0;border:1px solid var(--smc-border);border-radius:var(--smc-radius);overflow:hidden;background:var(--smc-surface)}
.smc-color-card img{display:block;width:100%;aspect-ratio:4/3;object-fit:cover;cursor:zoom-in}
.smc-color-card figcaption{display:block;padding:18px}
.smc-color-card strong,.smc-color-card span{display:block}
.smc-color-card strong{font-family:var(--smc-font-heading);color:var(--smc-primary);font-size:21px;margin-bottom:7px}
.smc-color-card span{font-size:15px;line-height:1.65}
.smc-color-note{margin:20px 0 0;padding:18px 20px;border-left:4px solid var(--smc-accent);background:color-mix(in srgb,var(--smc-accent) 6%,var(--smc-bg));border-radius:0 var(--smc-radius) var(--smc-radius) 0}
.smc-care{display:grid;grid-template-columns:.8fr 1.2fr;gap:30px;background:linear-gradient(135deg,color-mix(in srgb,var(--smc-primary) 8%,var(--smc-bg)),var(--smc-bg))}
.smc-steps{list-style:none;margin:0;padding:0;display:grid;gap:12px}
.smc-steps li{display:grid;grid-template-columns:42px 1fr;gap:14px;align-items:start;padding:16px;background:var(--smc-bg);border:1px solid var(--smc-border);border-radius:var(--smc-radius)}
.smc-steps li>span{display:grid;place-items:center;width:42px;height:42px;border-radius:50%;background:var(--smc-primary);color:white;font-family:var(--smc-font-heading);font-weight:700}
.smc-steps p{margin:5px 0 0}
.smc-spec-wrap{display:grid;grid-template-columns:1.1fr .9fr;gap:20px;align-items:start}
.smc-specs table{width:100%;border-collapse:separate;border-spacing:0;border:1px solid var(--smc-border);border-radius:var(--smc-radius);overflow:hidden}
.smc-specs th,.smc-specs td{padding:13px 15px;text-align:left;vertical-align:top;border-bottom:1px solid var(--smc-border)}
.smc-specs tr:last-child th,.smc-specs tr:last-child td{border-bottom:0}
.smc-specs th{width:44%;color:var(--smc-primary);background:var(--smc-surface);font-weight:700}
.smc-decision{padding:22px;background:color-mix(in srgb,var(--smc-primary) 9%,var(--smc-bg));border-radius:var(--smc-radius);border:1px solid color-mix(in srgb,var(--smc-primary) 18%,var(--smc-border))}
.smc-decision strong{display:block;color:var(--smc-primary);font-family:var(--smc-font-heading);font-size:21px;margin-bottom:10px}
.smc-decision p:last-child{margin-bottom:0}
.smc-faq details{border-top:1px solid var(--smc-border)}
.smc-faq details:last-child{border-bottom:1px solid var(--smc-border)}
.smc-faq summary{display:flex;justify-content:space-between;gap:18px;align-items:center;padding:18px 4px;cursor:pointer;color:var(--smc-primary);font-family:var(--smc-font-heading);font-weight:700;list-style:none}
.smc-faq summary::-webkit-details-marker{display:none}
.smc-faq summary span{display:grid;place-items:center;flex:0 0 30px;width:30px;height:30px;border-radius:50%;background:var(--smc-surface);color:var(--smc-accent);font-size:20px;transition:transform .2s ease}
.smc-faq details[open] summary span{transform:rotate(45deg)}
.smc-faq details p{padding:0 46px 18px 4px;margin:0}
.smc-root.smc-js [data-smc-reveal]{opacity:0;transform:translateY(16px);transition:opacity .55s ease,transform .55s ease}
.smc-root.smc-js [data-smc-reveal].is-visible{opacity:1;transform:none}
@container smc (max-width:700px){.smc-intro,.smc-care,.smc-spec-wrap{grid-template-columns:1fr}.smc-intro{padding:22px;gap:22px}.smc-intro-media{order:-1}.smc-feature-grid,.smc-color-grid{grid-template-columns:1fr}.smc-colors,.smc-care,.smc-specs,.smc-faq{padding:22px}.smc-feature{padding:24px}.smc-feature h2,.smc-feature h3{font-size:20px}.smc-care{gap:10px}.smc-section-head{margin-bottom:16px}}
@container smc (max-width:430px){.smc-root{font-size:15px}.smc-root h2{font-size:23px}.smc-intro,.smc-colors,.smc-care,.smc-specs,.smc-faq{padding:18px;border-radius:var(--smc-radius)}.smc-quickfacts{grid-template-columns:1fr}.smc-quickfacts div{display:grid;grid-template-columns:90px 1fr;align-items:center;gap:8px}.smc-quickfacts span{margin-top:0}.smc-feature-grid{gap:12px}.smc-feature{padding:20px}.smc-number{right:16px;top:14px;font-size:24px}.smc-color-card figcaption{padding:15px}.smc-steps li{grid-template-columns:34px 1fr;padding:13px}.smc-steps li>span{width:34px;height:34px}.smc-specs th,.smc-specs td{display:block;width:100%;padding:10px 12px}.smc-specs th{border-bottom:0;padding-bottom:4px}.smc-specs td{padding-top:4px}.smc-faq summary{font-size:15px}.smc-faq details p{padding-right:4px}}
.smc-root a{color:var(--smc-accent);font-weight:600;text-decoration:underline;text-underline-offset:3px}
.smc-decision ul,.smc-specs ul{margin:0 0 16px;padding-left:22px;list-style:disc}
.smc-decision li::marker,.smc-specs li::marker{color:var(--smc-accent)}
.smc-decision li,.smc-specs li{margin:6px 0}
.smc-more{padding-top:14px;border-top:1px solid color-mix(in srgb,var(--smc-primary) 18%,var(--smc-border));font-size:14px}
.smc-specs>.smc-intro-media{max-width:590px;margin:0 auto}

